import socket,struct,time,os
def execute(port,ttl,timeout=.2):
    if type(port) is not int or not 1<=port<=65535 or type(ttl) is not int or not 1<=ttl<=255:raise ValueError('invalid port/TTL')
    if not isinstance(timeout,(float,int)) or isinstance(timeout,bool) or not 0<timeout<=1:raise ValueError('invalid timeout')
    IP_RECVERR=11
    payload=b'opsforge-trace-'+os.urandom(8)
    with socket.socket(socket.AF_INET,socket.SOCK_DGRAM) as probe:
        probe.setsockopt(socket.SOL_IP,IP_RECVERR,1)
        probe.setsockopt(socket.IPPROTO_IP,socket.IP_TTL,ttl)
        probe.setblocking(False);probe.connect(('127.0.0.1',port));probe.send(payload)
        deadline=time.monotonic()+timeout
        while time.monotonic()<deadline:
            try:data,ancillary,flags,address=probe.recvmsg(4096,512,socket.MSG_ERRQUEUE|socket.MSG_DONTWAIT)
            except BlockingIOError:time.sleep(.005);continue
            if data!=payload:continue
            for level,kind,value in ancillary:
                if level==socket.SOL_IP and kind==IP_RECVERR and len(value)>=24:
                    number,origin,icmp_type,icmp_code,pad,info,detail=struct.unpack('=IBBBBII',value[:16])
                    offender=socket.inet_ntoa(value[20:24])
                    reached=origin==2 and icmp_type==3 and icmp_code==3
                    return {'ttl':ttl,'destination':'127.0.0.1','outcome':'destination_reached' if reached else 'other_error','origin':origin,'icmp_type':icmp_type,'icmp_code':icmp_code,'offender':offender}
        return {'ttl':ttl,'destination':'127.0.0.1','outcome':'no_error','origin':None,'icmp_type':None,'icmp_code':None,'offender':None}
```

原理补充：
traceroute 逐步提高报文 TTL/Hop Limit，根据中间节点返回的超时信息推断路径和往返延迟。实现可能用 UDP、ICMP 或 TCP。星号可能是过滤或限速，不必然是业务断链；非对称路由和 ECMP 也会影响结果。

